import{z as B,x as d,o as r,c as A,q as t,j as l,D as E,d as o,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"引用计数 GC","description":"","frontmatter":{"title":"引用计数 GC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/refcounting-gc.md","filePath":"cs/refcounting-gc.md","lastUpdated":1791063341000}'),c={name:"cs/refcounting-gc.md"};function C(p,a,f,h,m,u){const n=d("Mermaid");return r(),A("div",null,[a[2]||(a[2]=t('<h1 id="引用计数-gc" tabindex="-1">引用计数 GC <a class="header-anchor" href="#引用计数-gc" aria-label="Permalink to &quot;引用计数 GC&quot;">​</a></h1><div class="epigraph"><p>每个对象记有多少指针指向它，到零则释放。及时，但循环会泄漏，除非配合循环检测或弱引用；更新计数的原子开销在多核上显著。</p><footer>—— 据 Collins, A Method for Overlapping and Erasure of Lists, 1960；Jones 手册；对照[线性类型](/cs/linear-ownership) 整理</footer></div><p>上一课<a href="/cs/copying-gc">复制式</a> 靠追踪。缺口是 <strong>RC</strong>：赋值时减旧加新。Python、Swift（ARC）、部分 Rust <code>Rc</code>。本课钉循环与原子，写屏障下一课是追踪式的。不把 RC 当线性类型——线性是静态零计数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>追踪有暂停；RC 希望即时回收。循环：<code>a.p=b; b.p=a</code> 计数永不为零。解决：周期检测、或禁止循环（所有权树）、或弱引用打破。缺口是<strong>计数协议</strong>，不是 Cheney 扫描。</p><p>多线程：计数更新要原子或缓冲（如 Cobsen 的缓冲 RC）。</p><h3 id="rc-不是-malloc-free-手工配对" tabindex="-1">RC 不是 malloc/free 手工配对 <a class="header-anchor" href="#rc-不是-malloc-free-手工配对" aria-label="Permalink to &quot;RC 不是 malloc/free 手工配对&quot;">​</a></h3><p>程序员不写 free；赋值重载负责。但循环与性能仍是实现问题。C++ <code>shared_ptr</code> 循环同样漏。</p><p><span class="marginnote">常见误区：初学者以为 <code>shared_ptr</code> 的循环泄漏是「忘了 free」。实际一个 <code>free</code> 都没少写——赋值时计数照常减了，只是环内互指让每个对象都还剩 1，谁也到不了 0。</span></p><p><span class="marginnote">直觉类比：追踪式 GC 像定期大扫除——平时不动、扫时全场暂停；RC 像随手归位——谁用完谁立刻收。代价是每次交接都要记账：借出 +1、归还 -1，账本本身成了运行时开销。</span></p><p><span class="marginnote">Collins 1960。Bacon、Rajan 等循环回收。Swift ARC。Jones 手册 RC 章。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写指针槽：<code>decref(old); incref(new)</code>。零则跑析构再释放。优化：局部变量可省略（编译器 RC 消除，类似线性）。</p>',13)),(r(),l(i,null,{default:E(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASG%5B%22%E6%8C%87%E9%92%88%E8%B5%8B%E5%80%BC%22%5D%20--%3E%20DEC%5B%22%E6%97%A7%E8%AE%A1%E6%95%B0%20-1%22%5D%0A%20%20ASG%20--%3E%20INC%5B%22%E6%96%B0%E8%AE%A1%E6%95%B0%20%2B1%22%5D%0A%20%20DEC%20--%3E%20Z%5B%22%E5%88%B0%200%20%E5%88%99%E6%9E%90%E6%9E%84%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与复制：有的系统幼代追踪、老年代 RC，点名。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[o("原子："),e("code",null,"increment"),o(" 争用热对象。缓冲：把 RC 操作记入线程本地，批量。不要在析构里再形成复杂图而不重入。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},[o("数字实例：多核下每秒百万次指针赋值，若每次都原子 "),e("code",null,"fetch_add"),o("，同一热对象的计数缓存行会在核间来回弹跳。缓冲 RC 把一批操作合并后一次刷入，原子操作次数从 \\(N\\) 降到约 \\(N/\\text{缓冲大小}\\)。")])],-1)),(r(),l(i,null,{default:E(()=>[s(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASG%5B%22%E7%BA%BF%E7%A8%8B%E5%86%85%E6%8C%87%E9%92%88%E8%B5%8B%E5%80%BC%22%5D%20--%3E%20BUF%5B%22%E8%AE%B0%E5%85%A5%E7%BA%BF%E7%A8%8B%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%86%B2%EF%BC%9A%2B%E6%96%B0%E5%AF%B9%E8%B1%A1%20%2F%20-%E6%97%A7%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20BUF%20--%3E%20FULL%7B%22%E7%BC%93%E5%86%B2%E6%BB%A1%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20FULL%20--%3E%7C%22%E6%9C%AA%E6%BB%A1%22%7C%20CONT%5B%22%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%EF%BC%8C%E9%9B%B6%E5%8E%9F%E5%AD%90%E6%93%8D%E4%BD%9C%22%5D%0A%20%20FULL%20--%3E%7C%22%E6%BB%A1%22%7C%20FLUSH%5B%22%E5%90%88%E5%B9%B6%E5%8E%BB%E9%87%8D%EF%BC%8C%E6%89%B9%E9%87%8F%E5%88%B7%E5%85%A5%E5%85%A8%E5%B1%80%E8%AE%A1%E6%95%B0%22%5D%0A%20%20FLUSH%20--%3E%20Z%7B%22%E6%9C%89%E8%AE%A1%E6%95%B0%E5%BD%92%200%3F%22%7D%0A%20%20Z%20--%3E%7C%22%E6%98%AF%22%7C%20FREE%5B%22%E6%9E%90%E6%9E%84%E5%B9%B6%E9%87%8A%E6%94%BE%E8%AF%A5%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20Z%20--%3E%7C%22%E5%90%A6%22%7C%20CONT%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>与<a href="/cs/null-option">Option</a>：空指针不 incref。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写写屏障卡表。后课默认：RC 及时但不收循环。下一课写屏障与卡表——追踪分代用。</p><p>也不把 RC 当文件系统链接计数课（思想类似，对象不同）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RC：赋值维护计数，零则释放。</li><li>循环需额外机制；多核要原子或缓冲。</li><li>与静态线性类型不同层。</li><li>出处：Collins, 1960；Jones 手册；对照 Bacon 等。</li></ul>',6))])}const _=B(c,[["render",C]]);export{D as __pageData,_ as default};
